<?php
namespace EIPSI\ExternalApi;
final class OperationsAdmin {
    public static function dispatch(string $action,array $p): array {
        // Admin::dispatch already checks capability, POST, origin and nonce.
        Operations::admin();$o=new Operations();
        if($action==='ops_settings'){if(!isset($p['values'],$p['revision'])||!is_array($p['values'])||!is_int($p['revision']))throw new ApiError('eipsi_external_invalid_input',400);return OperationsSettings::save($p['values'],$p['revision']);}
        if($action==='ops_health')return ExternalApiHealth::inspect();
        if($action==='ops_maintenance')return $o->maintenance();if($action==='ops_cleanup')return $o->maintenance(true);
        if($action==='ops_header')return array('authorization_received'=>($_SERVER['HTTP_AUTHORIZATION']??null)==='EIPSI-Diagnostic');
        if(in_array($action,array('ops_revoke','ops_purge'),true)){if(!isset($p['id'],$p['confirmation'])||!is_string($p['id'])||!is_string($p['confirmation']))throw new ApiError('eipsi_external_invalid_input',400);if($action==='ops_revoke')$o->revoke($p['id'],$p['confirmation']);else$o->purge($p['id'],$p['confirmation']);return array('completed'=>true);}
        throw new ApiError('eipsi_external_invalid_input',400);
    }
    private static function page(string $key): int {$v=$_GET[$key]??'1';return is_scalar($v)&&ctype_digit((string)$v)?max(1,min(10000,(int)$v)):1;}
    private static function pager(array $page,string $key): void {echo '<p>';if($page['page']>1)echo '<a class="button" href="'.esc_url(add_query_arg(array($key=>$page['page']-1,'api_section'=>$key==='api_exports_page'?'exports':'audit'))).('">'.esc_html(eipsi_admin_translate('Previous')).'</a> ');echo esc_html(eipsi_admin_format('Page %d',(int)$page['page'])).' ';if($page['has_more'])echo '<a class="button" href="'.esc_url(add_query_arg(array($key=>$page['page']+1,'api_section'=>$key==='api_exports_page'?'exports':'audit'))).('">'.esc_html(eipsi_admin_translate('Next')).'</a>');echo '</p>';}
    public static function render(): void {
        if(!current_user_can('manage_options'))return;
        try{$h=ExternalApiHealth::inspect();$o=new Operations();$exports=$o->exports(self::page('api_exports_page'));$filters=array();foreach(array('key','event','from','to','export')as$k)if(isset($_GET['api_audit_'.$k])&&is_string($_GET['api_audit_'.$k]))$filters[$k]=sanitize_text_field(wp_unslash($_GET['api_audit_'.$k]));$audit=$o->audit($filters,self::page('api_audit_page'));$metrics=OperationsMetrics::recent(time());}
        catch(\Throwable $e){echo ('<p role="alert">'.esc_html(eipsi_admin_translate('API operations are unavailable. Review migrations and the local connection.')).'</p>');return;}
        echo '<section id="eipsi-api-operations" data-nonce="'.esc_attr(wp_create_nonce('eipsi_external_api')).'" data-endpoint="'.esc_url(admin_url('admin-ajax.php')).'"><p role="status" class="api-message" data-ops-message></p>';
        Admin::panel('health',eipsi_admin_translate('Health and maintenance'),eipsi_admin_translate('Check API readiness: connection, schema, export preparation and cleanup. Notices explain what to check; diagnostics do not modify responses.'));
        echo ('<h3>'.esc_html(eipsi_admin_translate('System diagnostics')).'</h3><table class="widefat striped"><tbody>');foreach($h['checks']as$key=>$check){$color=array('OK'=>'#167146','WARNING'=>'#966000','ERROR'=>'#b32d2e')[$check['state']];echo '<tr><th>'.esc_html(array('configuration'=>eipsi_admin_translate('Configuration'),'database'=>eipsi_admin_translate('Database'),'storage'=>eipsi_admin_translate('Storage'),'worker'=>eipsi_admin_translate('Export preparation'),'maintenance'=>eipsi_admin_translate('Maintenance'),'cleanup'=>eipsi_admin_translate('Cleanup'),'schema'=>eipsi_admin_translate('Schema and migrations'),'transactions'=>eipsi_admin_translate('Transactions'),'integrity'=>eipsi_admin_translate('Export integrity'),'cron'=>eipsi_admin_translate('Scheduled execution'),'tls'=>eipsi_admin_translate('Secure HTTPS connection'),'proxy'=>eipsi_admin_translate('Proxy and headers'),'temporary_storage'=>eipsi_admin_translate('Temporary files'),'php'=>eipsi_admin_translate('PHP resources'),'rate_limiter'=>eipsi_admin_translate('Request protection'),'cors'=>eipsi_admin_translate('Cross-site access'),'clock'=>eipsi_admin_translate('Clock and time zone'))[$key]??$key).'</th><td style="color:'.esc_attr($color).'"><strong>'.esc_html($check['state']).'</strong></td><td>'.esc_html($check['message']).'</td></tr>';}echo '</tbody></table>';
        echo '<div class="api-stats">';$statLabels=array('exports'=>eipsi_admin_translate('Total exports'),'active_exports'=>eipsi_admin_translate('Active exports'),'preparing'=>eipsi_admin_translate('Preparing'),'ready_exports'=>eipsi_admin_translate('Ready exports'),'failed_exports'=>eipsi_admin_translate('Failed exports'),'logical_bytes'=>eipsi_admin_translate('Total derived bytes'),'preparing_bytes'=>eipsi_admin_translate('Preparing bytes'),'ready_bytes'=>eipsi_admin_translate('Ready bytes'),'terminal_bytes'=>eipsi_admin_translate('Bytes pending cleanup'),'stale_preparing'=>eipsi_admin_translate('Delayed preparations'),'expired_leases'=>eipsi_admin_translate('Expired leases'),'cleanup_pending'=>eipsi_admin_translate('Exports awaiting cleanup'),'active_keys'=>eipsi_admin_translate('Active keys'));foreach($h['statistics']as$k=>$v)echo '<div class="api-stat">'.esc_html($statLabels[$k]??$k).'<strong>'.(int)$v.'</strong></div>';echo ('</div><p>'.esc_html(eipsi_admin_translate('These sizes represent logical derived data for this site, not physical database space.')).'</p><p>'.esc_html(eipsi_admin_translate('Next maintenance:')).' ').esc_html($h['next_maintenance']?gmdate('Y-m-d H:i:s',$h['next_maintenance']).' UTC':eipsi_admin_translate('No scheduled event')).'</p>';
        foreach(array('last_tick','last_success','last_cleanup','last_worker_activity')as$k)echo '<p>'.esc_html(array('last_tick'=>eipsi_admin_translate('Last execution'),'last_success'=>eipsi_admin_translate('Last successful maintenance'),'last_cleanup'=>eipsi_admin_translate('Last cleanup'),'last_worker_activity'=>eipsi_admin_translate('Last preparation activity'))[$k]).': '.esc_html(empty($h['maintenance'][$k])?eipsi_admin_translate('No record'):gmdate('Y-m-d H:i:s',$h['maintenance'][$k]).' UTC').'</p>';
        foreach(array('ops_maintenance'=>eipsi_admin_translate('Run API maintenance now'),'ops_cleanup'=>eipsi_admin_translate('Clean up expired exports now'),'ops_header'=>eipsi_admin_translate('Check Authorization reception'))as$action=>$label)echo '<form data-operation="'.esc_attr($action).'" style="display:inline-block;margin-right:8px"><button class="button">'.esc_html($label).'</button></form>';
        echo '</section>';Admin::panel('limits',eipsi_admin_translate('Usage limits'),eipsi_admin_translate('Adjust export retention and resource limits. Each field shows its allowed range. Keep defaults unless capacity needs to change.'));
        echo ('<p>'.esc_html(eipsi_admin_translate('Lifetime and maximum size are fixed when an export is created. Aggregate quotas, maintenance budget and suggested polling interval apply to future operations. Ready exports retain their content.')).'</p><form data-operation="ops_settings" data-revision="').(int)$h['settings']['revision'].'"><table class="form-table">';
        $labels=array('export_ttl'=>eipsi_admin_translate('Export lifetime (seconds)'),'active_per_key'=>eipsi_admin_translate('Active exports per key'),'preparing_per_key'=>eipsi_admin_translate('Preparing exports per key'),'global_preparing'=>eipsi_admin_translate('Preparing exports per site'),'export_bytes'=>eipsi_admin_translate('Maximum logical export size (bytes)'),'aggregate_bytes'=>eipsi_admin_translate('Maximum aggregate logical size (bytes)'),'worker_seconds'=>eipsi_admin_translate('Preparation time per run (seconds)'),'worker_steps'=>eipsi_admin_translate('Maximum steps per run'),'cleanup_batch'=>eipsi_admin_translate('Exports per cleanup batch'),'poll_seconds'=>eipsi_admin_translate('Suggested polling interval (seconds)'),'audit_days'=>eipsi_admin_translate('Operational audit retention (days)'),'key_audit_days'=>eipsi_admin_translate('Key and configuration history (days)'));
        foreach(OperationsSettings::bounds()as$k=>$b)echo '<tr><th><label for="ops-'.esc_attr($k).'">'.esc_html($labels[$k]).'</label></th><td><input id="ops-'.esc_attr($k).'" type="number" step="1" min="'.$b[0].'" max="'.$b[1].'" name="'.esc_attr($k).'" value="'.(int)$h['settings'][$k].('" required><p class="description">'.esc_html(eipsi_admin_translate('Minimum')).' ').$b[0].' · '.eipsi_admin_translate('Maximum').' '.$b[1].' · '.eipsi_admin_translate('Default').' '.$b[2].'</p></td></tr>';
        echo ('</table><button class="button button-primary">'.esc_html(eipsi_admin_translate('Save limits')).'</button></form></section>');Admin::panel('exports',eipsi_admin_translate('Exports'),eipsi_admin_translate('Follow files generated by integrations. Preparing files cannot be downloaded: wait until Ready. Revoking prevents new deliveries; purging deletes only derived artifacts of a terminal export, without deleting responses.'));echo '<div class="api-table"><table class="widefat striped"><thead><tr>';foreach(array(eipsi_admin_translate('Export / key / study'),eipsi_admin_translate('Status / format'),eipsi_admin_translate('Created / as_of / expires (UTC)'),eipsi_admin_translate('Rows / logical bytes'),eipsi_admin_translate('Progress'),eipsi_admin_translate('Diagnostics'),eipsi_admin_translate('Actions'))as$t)echo '<th>'.esc_html($t).'</th>';echo '</tr></thead><tbody>';
        foreach($exports['items']as$r){echo '<tr><td><code>'.esc_html($r['id']).'</code><br>'.esc_html($r['key_name']??$r['key_id']).'<br>'.esc_html($r['study_code']).'</td><td>'.Admin::badge($r['state']).'<br>'.esc_html($r['format']).'</td><td>'.esc_html(gmdate('c',(int)$r['created_at'])).'<br>'.esc_html($r['as_of']).'<br>'.esc_html(gmdate('c',(int)$r['expires_at'])).'</td><td>'.(int)$r['row_count'].' filas<br>'.(int)$r['byte_count'].' de descarga<br>'.(int)$r['storage_bytes'].' derivados</td><td>'.(int)$r['next_source'].' / '.(int)$r['source_count'];if((int)$r['source_count']>0)echo ' ('.min(100,(int)floor(100*$r['next_source']/$r['source_count'])).'%)';echo '</td><td>'.esc_html(($r['failure_reason']??'').' '.($r['error_code']??'')).'</td><td>';
            if(in_array($r['state'],array('READY','PREPARING'),true))self::actionForm('ops_revoke','REVOCAR',$r['id'],eipsi_admin_translate('Revoke'));elseif(in_array($r['state'],array('REVOKED','FAILED','EXPIRED'),true)&&$r['purged_at']===null)self::actionForm('ops_purge','PURGAR',$r['id'],eipsi_admin_translate('Purge artifacts'));echo '</td></tr>';
        }if(!$exports['items'])echo ('<tr><td colspan="7">'.esc_html(eipsi_admin_translate('There are no exports yet. Create them from an integration; see How to connect for instructions.')).'</td></tr>');echo '</tbody></table></div>';self::pager($exports,'api_exports_page');echo '</section>';
        Admin::panel('audit',eipsi_admin_translate('Audit'),eipsi_admin_translate('Review integration operations and their times. Filter by key, event, date or export. The log retains operational context without exposing secrets or responses.'));
        echo '<form method="get"><input type="hidden" name="page" value="eipsi-configuration"><input type="hidden" name="tab" value="external-api"><input type="hidden" name="api_section" value="audit">';foreach(array('key'=>eipsi_admin_translate('Key ID'),'event'=>eipsi_admin_translate('Event'),'export'=>eipsi_admin_translate('Export ID'),'from'=>eipsi_admin_translate('From UTC'),'to'=>eipsi_admin_translate('Until UTC'))as$k=>$label)echo '<label style="display:inline-block;margin:6px">'.esc_html($label).' <input name="api_audit_'.esc_attr($k).'" type="'.(in_array($k,array('from','to'),true)?'date':'text').'" value="'.esc_attr($filters[$k]??'').'"></label>';echo ('<button class="button">'.esc_html(eipsi_admin_translate('Filter')).'</button></form><div class="api-table"><table class="widefat striped"><thead><tr><th>UTC</th><th>'.esc_html(eipsi_admin_translate('Event / count')).'</th><th>'.esc_html(eipsi_admin_translate('Key / export')).'</th><th>'.esc_html(eipsi_admin_translate('Operational context')).'</th></tr></thead><tbody>');
        foreach($audit['items']as$r)echo '<tr><td>'.esc_html(gmdate('c',(int)$r['created_at'])).'</td><td>'.esc_html($r['event']).' / '.(int)$r['event_count'].'</td><td>'.esc_html($r['key_id']).'<br>'.esc_html($r['export_id']).'</td><td><code>'.esc_html(json_encode($r['details'],JSON_UNESCAPED_SLASHES)).'</code></td></tr>';if(!$audit['items'])echo ('<tr><td colspan="4">'.esc_html(eipsi_admin_translate('No events match the selected filters.')).'</td></tr>');echo '</tbody></table></div>';self::pager($audit,'api_audit_page');echo '</section>';
        Admin::panel('metrics',eipsi_admin_translate('Metrics from the last 30 days'),eipsi_admin_translate('Review requests, errors and downloads by operation. Counters are local and aggregated to monitor usage and capacity without identifying participants.'));
        echo ('<p>'.esc_html(eipsi_admin_translate('Requests, errors, total time, generated or download-admitted bytes, limits reached, cleanup and preparation failures. Admitted bytes do not prove complete client reception. No participant dimensions or external telemetry.')).'</p><div class="api-table"><table class="widefat striped"><thead><tr><th>'.esc_html(eipsi_admin_translate('Operation')).'</th><th>'.esc_html(eipsi_admin_translate('Requests')).'</th><th>'.esc_html(eipsi_admin_translate('Errors')).'</th><th>'.esc_html(eipsi_admin_translate('Total time (ms)')).'</th><th>'.esc_html(eipsi_admin_translate('Generated bytes')).'</th><th>'.esc_html(eipsi_admin_translate('Downloaded bytes')).'</th><th>'.esc_html(eipsi_admin_translate('Limits reached')).'</th><th>'.esc_html(eipsi_admin_translate('Cleanups')).'</th><th>'.esc_html(eipsi_admin_translate('Preparation failures')).'</th></tr></thead><tbody>');foreach($metrics as$row){echo '<tr>';foreach($row as$value)echo '<td>'.esc_html((string)$value).'</td>';echo '</tr>';}if(!$metrics)echo ('<tr><td colspan="9">'.esc_html(eipsi_admin_translate('No activity has been recorded yet.')).'</td></tr>');echo '</tbody></table></div><p>'.esc_html(eipsi_admin_translate('Fixed limits per minute and key: authenticated 120; discovery 60; data 30; bulk 5; create export 6; export status 90; pages/manifest/dictionary 60; download 20. These limits apply per minute and key. When reached, the integration must wait the indicated time before retrying.')).'</p></section></section>';
        ?>
        <script>(()=>{'use strict';const host=document.getElementById('eipsi-api-operations');host.querySelectorAll('form[data-operation]').forEach(form=>form.addEventListener('submit',async event=>{event.preventDefault();const p={operation:form.dataset.operation,nonce:host.dataset.nonce};if(p.operation==='ops_settings'){p.revision=Number(form.dataset.revision);p.values=Object.fromEntries([...form.querySelectorAll('input[name]')].map(x=>[x.name,Number(x.value)]));}if(form.dataset.id){p.id=form.dataset.id;p.confirmation=form.elements.confirmation.value;if(!window.confirm(window.EIPSIAdminI18n.f('Confirm %1$s for export %2$s?',form.dataset.operation,p.id)))return;}const button=form.querySelector('button');button.disabled=true;try{const headers=p.operation==='ops_header'?{Authorization:'EIPSI-Diagnostic'}:{};const r=await fetch(host.dataset.endpoint,{method:'POST',headers,credentials:'same-origin',cache:'no-store',body:new URLSearchParams({action:'eipsi_external_api',payload:JSON.stringify(p)})});const j=await r.json();if(!r.ok||!j.success)throw new Error(j.data?.message||<?php echo wp_json_encode(eipsi_admin_translate("Could not complete the operation.")); ?>);if(p.operation==='ops_header')host.querySelector('[data-ops-message]').textContent=j.data.authorization_received?<?php echo wp_json_encode(eipsi_admin_translate('Authorization received successfully.')); ?>:<?php echo wp_json_encode(eipsi_admin_translate('The server did not deliver the diagnostic header.')); ?>;else window.location.reload();}catch(e){host.querySelector('[data-ops-message]').textContent=e.message;}finally{button.disabled=false;}}));})();</script>
        <?php
    }
    private static function actionForm(string $op,string $verb,string $id,string $label): void {echo '<form data-operation="'.esc_attr($op).'" data-id="'.esc_attr($id).'"><label>'.esc_html(eipsi_admin_format('Type %s',$verb.' '.$id)).'<input name="confirmation" required autocomplete="off"></label><button class="button">'.esc_html($label).'</button></form>';}
}
